import Foundation

enum AudioQuality: Int, CaseIterable, Identifiable {
    case mp3 = 1
    case cd = 2
    case hiRes = 3
    case hiResMax = 4

    var id: Int { rawValue }

    var label: String {
        switch self {
        case .mp3: return "MP3"
        case .cd: return "CD"
        case .hiRes: return "Hi-Res"
        case .hiResMax: return "Max"
        }
    }

    var detail: String {
        switch self {
        case .mp3: return "MP3 · 320 kbps"
        case .cd: return "FLAC · 16-bit / 44.1 kHz"
        case .hiRes: return "FLAC · 24-bit / up to 96 kHz"
        case .hiResMax: return "FLAC · 24-bit / up to 192 kHz"
        }
    }
}

enum OutputFormat: String, CaseIterable, Identifiable {
    case original, alac, aac, mp3

    var id: String { rawValue }

    var label: String {
        switch self {
        case .original: return "Original (FLAC / MP3)"
        case .alac: return "ALAC (Apple Lossless)"
        case .aac: return "AAC"
        case .mp3: return "MP3"
        }
    }

    /// Value for streamrip's --codec flag. nil = keep what Qobuz delivers.
    var codecArgument: String? {
        switch self {
        case .original: return nil
        case .alac: return "ALAC"
        case .aac: return "AAC"
        case .mp3: return "MP3"
        }
    }
}

enum AuthMethod: String, CaseIterable, Identifiable {
    case token, email

    var id: String { rawValue }

    var label: String {
        switch self {
        case .token: return "User ID + Token"
        case .email: return "Email + Password"
        }
    }

    var keychainAccount: String { self == .token ? "qobuz-token" : "qobuz-password" }
    var savedFlagKey: String { "hasSecret.\(rawValue)" }
}

enum JobStatus: Equatable {
    case queued
    case running
    case done
    case warning(String)
    case failed(String)
    case cancelled

    var isFinished: Bool {
        switch self {
        case .queued, .running: return false
        default: return true
        }
    }
}

struct DownloadJob: Identifiable, Equatable {
    let id = UUID()
    let url: String
    let kind: String
    let name: String
    var status: JobStatus = .queued

    init(url: String) {
        self.url = url
        let d = DownloadJob.describe(url)
        kind = d.kind
        name = d.name
    }

    /// Turns a Qobuz link into something readable, e.g.
    /// https://www.qobuz.com/us-en/album/blue-train-john-coltrane/0060253747386 → ("Album", "Blue Train John Coltrane")
    static func describe(_ link: String) -> (kind: String, name: String) {
        guard let u = URL(string: link) else { return ("Link", link) }
        let parts = u.pathComponents.filter { $0 != "/" }
        let kinds = ["album", "track", "playlist", "artist", "label"]
        guard let i = parts.firstIndex(where: { kinds.contains($0.lowercased()) }) else {
            return ("Link", link)
        }
        let kind = parts[i].capitalized
        let rest = Array(parts[(i + 1)...])
        if rest.count >= 2 {
            return (kind, rest[0].replacingOccurrences(of: "-", with: " ").capitalized)
        } else if let only = rest.first {
            return (kind, "ID \(only)")
        }
        return (kind, link)
    }
}

struct LogLine: Identifiable {
    let id = UUID()
    let text: String
    let isError: Bool
}

extension String {
    var trimmed: String { trimmingCharacters(in: .whitespacesAndNewlines) }
}

