import SwiftUI
import AppKit

@MainActor
final class AppModel: ObservableObject {
    enum EngineState: Equatable {
        case checking
        case missing
        case installing
        case ready(String)

        var isReady: Bool { if case .ready = self { return true } else { return false } }
    }

    // UI state
    @Published var jobs: [DownloadJob] = []
    @Published var log: [LogLine] = []
    @Published var engine: EngineState = .checking
    @Published var homebrewMissing = false
    @Published var isRunning = false
    @Published var statusLine = ""
    @Published var showAccount = false
    @Published var linkDraft = ""

    // Saved preferences
    @Published var quality: AudioQuality { didSet { defaults.set(quality.rawValue, forKey: "quality") } }
    @Published var format: OutputFormat { didSet { defaults.set(format.rawValue, forKey: "format") } }
    @Published var folder: URL { didSet { defaults.set(folder.path, forKey: "folder") } }
    @Published var authMethod: AuthMethod { didSet { defaults.set(authMethod.rawValue, forKey: "authMethod") } }
    @Published var accountID: String { didSet { defaults.set(accountID, forKey: "accountID") } }
    @Published var skipRepeats: Bool { didSet { defaults.set(skipRepeats, forKey: "skipRepeats") } }

    private let defaults = UserDefaults.standard
    private let runner = ProcessRunner()      // downloads + installs (the Stop button targets this)
    private let helper = ProcessRunner()      // short checks like --version
    private var stopRequested = false

    init() {
        let d = UserDefaults.standard
        quality = AudioQuality(rawValue: d.integer(forKey: "quality")) ?? .hiResMax
        format = OutputFormat(rawValue: d.string(forKey: "format") ?? "") ?? .original
        if let p = d.string(forKey: "folder") {
            folder = URL(fileURLWithPath: p, isDirectory: true)
        } else {
            folder = Paths.defaultDownloads
        }
        authMethod = AuthMethod(rawValue: d.string(forKey: "authMethod") ?? "") ?? .token
        accountID = d.string(forKey: "accountID") ?? ""
        skipRepeats = d.bool(forKey: "skipRepeats")

        let r = runner
        _ = NotificationCenter.default.addObserver(
            forName: NSApplication.willTerminateNotification, object: nil, queue: nil
        ) { _ in r.stop() }

        Task { await checkEngine() }
    }

    // MARK: Account

    func hasSecret(for method: AuthMethod) -> Bool { defaults.bool(forKey: method.savedFlagKey) }

    var hasCredentials: Bool { !accountID.trimmed.isEmpty && hasSecret(for: authMethod) }

    func saveAccount(method: AuthMethod, account: String, secret: String) {
        authMethod = method
        accountID = account.trimmed
        let s = secret.trimmed
        if !s.isEmpty {
            // streamrip expects the MD5 of the password, so the plain password is never stored.
            let value = method == .token ? s : StreamripConfig.md5(s)
            if Keychain.save(value, account: method.keychainAccount) {
                defaults.set(true, forKey: method.savedFlagKey)
            } else {
                appendLog("Couldn't save to the Keychain.", isError: true)
            }
        }
        objectWillChange.send()
    }

    // MARK: Engine

    func checkEngine() async {
        engine = .checking
        guard let rip = Shell.which("rip") else { engine = .missing; return }
        let result = await helper.capture(rip, ["--version"])
        if result.code == 0 {
            let version = result.lines.last?.split(separator: " ").last.map(String.init) ?? "?"
            engine = .ready(version)
        } else {
            engine = .missing
            result.lines.forEach { appendLog($0) }
        }
    }

    func installEngine() async {
        guard !isRunning else { return }
        isRunning = true
        engine = .installing
        homebrewMissing = false
        statusLine = "Installing download engine…"
        appendLog("Installing streamrip + ffmpeg with Homebrew. This can take a few minutes.")
        let script = """
        export PATH="/opt/homebrew/bin:/usr/local/bin:$HOME/.local/bin:$PATH"
        export HOMEBREW_NO_AUTO_UPDATE=1
        if ! command -v brew >/dev/null 2>&1; then echo "Homebrew not found."; exit 3; fi
        brew install pipx ffmpeg || exit 1
        if pipx list 2>/dev/null | grep -q streamrip; then
          pipx upgrade streamrip
        else
          pipx install streamrip
        fi
        """
        let code = await runner.run("/bin/zsh", ["-c", script]) { [weak self] line in
            Task { @MainActor in self?.appendLog(line) }
        }
        if code == 3 { homebrewMissing = true }
        if code != 0 { appendLog("Engine install didn't finish (code \(code)).", isError: true) }
        isRunning = false
        statusLine = ""
        await checkEngine()
    }

    func updateEngine() async {
        guard !isRunning else { return }
        isRunning = true
        statusLine = "Updating download engine…"
        let script = """
        export PATH="/opt/homebrew/bin:/usr/local/bin:$HOME/.local/bin:$PATH"
        pipx upgrade streamrip || pipx install streamrip
        """
        _ = await runner.run("/bin/zsh", ["-c", script]) { [weak self] line in
            Task { @MainActor in self?.appendLog(line) }
        }
        isRunning = false
        statusLine = ""
        await checkEngine()
    }

    // MARK: Queue

    @discardableResult
    func addLinks(from text: String) -> Int {
        let junk = CharacterSet(charactersIn: "<>\"'(),")
        var added = 0
        for token in text.components(separatedBy: .whitespacesAndNewlines) {
            let link = token.trimmingCharacters(in: junk)
            let lower = link.lowercased()
            guard lower.hasPrefix("http"), lower.contains("qobuz.com") else { continue }
            if jobs.contains(where: { $0.url == link && !$0.status.isFinished }) { continue }
            jobs.append(DownloadJob(url: link))
            added += 1
        }
        if added > 0 {
            linkDraft = ""
        } else if !text.trimmed.isEmpty {
            appendLog("No Qobuz links found in what you pasted.", isError: true)
        }
        return added
    }

    func pasteAndAdd() {
        guard let s = NSPasteboard.general.string(forType: .string) else { return }
        if addLinks(from: s) == 0 { linkDraft = s }
    }

    func remove(_ job: DownloadJob) { jobs.removeAll { $0.id == job.id && $0.status != .running } }

    func retry(_ job: DownloadJob) {
        guard let i = jobs.firstIndex(where: { $0.id == job.id }), jobs[i].status.isFinished else { return }
        jobs[i].status = .queued
    }

    func retryFailed() {
        for i in jobs.indices {
            switch jobs[i].status {
            case .failed, .cancelled, .warning: jobs[i].status = .queued
            default: break
            }
        }
    }

    func clearFinished() { jobs.removeAll { $0.status.isFinished } }

    var queuedCount: Int { jobs.filter { $0.status == .queued }.count }

    var canStart: Bool { engine.isReady && !isRunning && queuedCount > 0 }

    func start() {
        guard canStart else { return }
        guard hasCredentials else { showAccount = true; return }
        Task { await runQueue() }
    }

    func stop() {
        stopRequested = true
        runner.stop()
    }

    private func runQueue() async {
        guard let rip = Shell.which("rip") else { engine = .missing; return }
        isRunning = true
        stopRequested = false
        statusLine = "Preparing…"

        guard await prepareConfig(rip: rip) else {
            isRunning = false
            statusLine = ""
            return
        }
        try? FileManager.default.createDirectory(at: folder, withIntermediateDirectories: true)

        while !stopRequested, let idx = jobs.firstIndex(where: { $0.status == .queued }) {
            let job = jobs[idx]
            jobs[idx].status = .running
            statusLine = "Downloading \(job.kind.lowercased()): \(job.name)"
            appendLog("▶ \(job.kind) — \(job.url)")

            var args = ["--config-path", Paths.config.path,
                        "--folder", folder.path,
                        "--quality", "\(quality.rawValue)",
                        "--no-progress"]
            if !skipRepeats { args.append("--no-db") }
            if let codec = format.codecArgument { args += ["--codec", codec] }
            args += ["url", job.url]

            let issues = IssueTracker()
            let code = await runner.run(rip, args) { [weak self] line in
                issues.inspect(line)
                Task { @MainActor in self?.appendLog(line) }
            }

            guard let i = jobs.firstIndex(where: { $0.id == job.id }) else { continue }
            if stopRequested {
                jobs[i].status = .cancelled
            } else if code != 0 {
                jobs[i].status = .failed(issues.summary ?? "Stopped with code \(code)")
            } else if let note = issues.summary {
                jobs[i].status = .warning(note)
            } else {
                jobs[i].status = .done
            }

            if issues.authProblem {
                appendLog("Qobuz rejected the login. Tokens expire now and then — paste a fresh one in Account.", isError: true)
                showAccount = true
                break
            }
        }

        scrubSecret()
        isRunning = false
        statusLine = ""
    }

    /// Makes sure QDL's private streamrip config exists, then writes the account + quality into it.
    private func prepareConfig(rip: String) async -> Bool {
        let fm = FileManager.default
        let path = Paths.config

        if !fm.fileExists(atPath: path.path) {
            // streamrip creates a default config when the one it's pointed at doesn't exist.
            _ = await helper.capture(rip, ["--config-path", path.path, "config", "path"])
            if !fm.fileExists(atPath: path.path) {
                _ = await helper.capture(rip, ["config", "path"])
                if fm.fileExists(atPath: Paths.defaultStreamripConfig.path) {
                    try? fm.copyItem(at: Paths.defaultStreamripConfig, to: path)
                }
            }
        }

        guard var toml = try? String(contentsOf: path, encoding: .utf8) else {
            appendLog("Couldn't create the engine settings file at \(path.path).", isError: true)
            return false
        }
        guard let secret = Keychain.read(authMethod.keychainAccount), !secret.isEmpty else {
            appendLog("Add your Qobuz account first.", isError: true)
            showAccount = true
            return false
        }

        toml = StreamripConfig.patch(toml, section: "qobuz", values: [
            ("quality", "\(quality.rawValue)"),
            ("use_auth_token", authMethod == .token ? "true" : "false"),
            ("email_or_userid", StreamripConfig.tomlString(accountID.trimmed)),
            ("password_or_token", StreamripConfig.tomlString(secret)),
        ])
        toml = StreamripConfig.patch(toml, section: "misc", values: [("check_for_updates", "false")])

        do {
            try toml.write(to: path, atomically: true, encoding: .utf8)
            try fm.setAttributes([.posixPermissions: 0o600], ofItemAtPath: path.path)
        } catch {
            appendLog("Couldn't write engine settings: \(error.localizedDescription)", isError: true)
            return false
        }
        return true
    }

    /// Removes the token/password from the config file once downloads finish.
    private func scrubSecret() {
        let path = Paths.config
        guard let toml = try? String(contentsOf: path, encoding: .utf8) else { return }
        let cleaned = StreamripConfig.patch(toml, section: "qobuz", values: [("password_or_token", "\"\"")])
        try? cleaned.write(to: path, atomically: true, encoding: .utf8)
    }

    // MARK: Folder

    func chooseFolder() {
        let panel = NSOpenPanel()
        panel.canChooseDirectories = true
        panel.canChooseFiles = false
        panel.canCreateDirectories = true
        panel.allowsMultipleSelection = false
        panel.prompt = "Choose"
        panel.directoryURL = folder
        if panel.runModal() == .OK, let url = panel.url { folder = url }
    }

    func revealFolder() {
        try? FileManager.default.createDirectory(at: folder, withIntermediateDirectories: true)
        NSWorkspace.shared.open(folder)
    }

    var folderDisplay: String {
        let home = NSHomeDirectory()
        let p = folder.path
        return p.hasPrefix(home) ? "~" + String(p.dropFirst(home.count)) : p
    }

    // MARK: Log

    func appendLog(_ text: String, isError: Bool? = nil) {
        let lower = text.lowercased()
        let err = isError ?? (lower.contains("error") || lower.contains("traceback") || lower.contains("failed"))
        log.append(LogLine(text: text, isError: err))
        if log.count > 3000 { log.removeFirst(log.count - 3000) }
    }
}

