import SwiftUI
import AppKit

// MARK: - Root

struct ContentView: View {
    @EnvironmentObject var model: AppModel

    var body: some View {
        HSplitView {
            ControlPanel()
                .frame(minWidth: 310, idealWidth: 330, maxWidth: 400)
            VSplitView {
                QueueView()
                    .frame(minHeight: 220)
                LogView()
                    .frame(minHeight: 110, idealHeight: 170)
            }
            .frame(minWidth: 460)
        }
        .sheet(isPresented: $model.showAccount) {
            AccountSheet().environmentObject(model)
        }
    }
}

// MARK: - Left panel

struct PanelSection<Content: View>: View {
    let title: String
    @ViewBuilder let content: () -> Content

    var body: some View {
        VStack(alignment: .leading, spacing: 8) {
            Text(title.uppercased())
                .font(.caption.weight(.semibold))
                .tracking(0.6)
                .foregroundStyle(.secondary)
            content()
        }
    }
}

struct ControlPanel: View {
    @EnvironmentObject var model: AppModel

    var body: some View {
        ScrollView {
            VStack(alignment: .leading, spacing: 20) {
                HStack(spacing: 10) {
                    Image(systemName: "waveform")
                        .font(.system(size: 20, weight: .semibold))
                        .foregroundStyle(Color.accentColor)
                    Text("QDL").font(.title2.weight(.bold))
                    Spacer()
                }

                EngineBanner()
                AccountRow()

                PanelSection(title: "Links") {
                    ZStack(alignment: .topLeading) {
                        TextEditor(text: $model.linkDraft)
                            .font(.system(size: 12, design: .monospaced))
                            .scrollContentBackground(.hidden)
                            .padding(6)
                        if model.linkDraft.isEmpty {
                            Text("Paste Qobuz album, track, playlist or artist links — one or many")
                                .font(.callout)
                                .foregroundStyle(.tertiary)
                                .padding(.horizontal, 11)
                                .padding(.vertical, 12)
                                .allowsHitTesting(false)
                        }
                    }
                    .frame(height: 100)
                    .background(RoundedRectangle(cornerRadius: 8).fill(Color(nsColor: .textBackgroundColor)))
                    .overlay(RoundedRectangle(cornerRadius: 8).stroke(Color.secondary.opacity(0.25)))

                    HStack {
                        Button {
                            model.pasteAndAdd()
                        } label: {
                            Label("Paste", systemImage: "doc.on.clipboard")
                        }
                        Spacer()
                        Button("Add to Queue") { model.addLinks(from: model.linkDraft) }
                            .keyboardShortcut(.return, modifiers: .command)
                            .disabled(model.linkDraft.trimmed.isEmpty)
                    }
                }

                PanelSection(title: "Quality") {
                    Picker("Quality", selection: $model.quality) {
                        ForEach(AudioQuality.allCases) { q in
                            Text(q.label).tag(q)
                        }
                    }
                    .pickerStyle(.segmented)
                    .labelsHidden()
                    Text(model.quality.detail)
                        .font(.callout)
                    Text("If a release isn't offered at this quality, the best lower one is used.")
                        .font(.caption)
                        .foregroundStyle(.secondary)
                        .fixedSize(horizontal: false, vertical: true)
                }

                PanelSection(title: "Format") {
                    Picker("Format", selection: $model.format) {
                        ForEach(OutputFormat.allCases) { f in
                            Text(f.label).tag(f)
                        }
                    }
                    .labelsHidden()
                    if model.format != .original {
                        Text("Converted with ffmpeg after downloading.")
                            .font(.caption)
                            .foregroundStyle(.secondary)
                    }
                }

                PanelSection(title: "Save to") {
                    HStack(spacing: 6) {
                        Image(systemName: "folder.fill").foregroundStyle(.secondary)
                        Text(model.folderDisplay)
                            .lineLimit(1)
                            .truncationMode(.middle)
                            .help(model.folder.path)
                    }
                    HStack {
                        Button("Choose…") { model.chooseFolder() }
                        Button("Show in Finder") { model.revealFolder() }
                    }
                    Toggle("Skip tracks I've already downloaded", isOn: $model.skipRepeats)
                        .toggleStyle(.checkbox)
                }
            }
            .padding(20)
        }
    }
}

struct EngineBanner: View {
    @EnvironmentObject var model: AppModel
    private let brewCommand = #"/bin/bash -c "$(curl -fsSL https://raw.githubusercontent.com/Homebrew/install/HEAD/install.sh)""#

    var body: some View {
        switch model.engine {
        case .checking:
            HStack(spacing: 8) {
                ProgressView().controlSize(.small)
                Text("Checking download engine…").font(.callout).foregroundStyle(.secondary)
            }
        case .installing:
            HStack(spacing: 8) {
                ProgressView().controlSize(.small)
                Text("Installing engine — this can take a few minutes").font(.callout)
            }
        case .ready(let version):
            HStack(spacing: 6) {
                Circle().fill(Color.green).frame(width: 7, height: 7)
                Text("Engine ready · streamrip \(version)")
                    .font(.caption)
                    .foregroundStyle(.secondary)
            }
        case .missing:
            VStack(alignment: .leading, spacing: 8) {
                Label("Download engine not installed", systemImage: "shippingbox")
                    .font(.callout.weight(.semibold))
                Text("QDL uses streamrip and ffmpeg to fetch from Qobuz. Install them once:")
                    .font(.caption)
                    .fixedSize(horizontal: false, vertical: true)
                HStack {
                    Button("Install Engine") { Task { await model.installEngine() } }
                        .buttonStyle(.borderedProminent)
                        .disabled(model.isRunning)
                    Button("Check Again") { Task { await model.checkEngine() } }
                }
                if model.homebrewMissing {
                    Text("Homebrew is needed first. Paste this into Terminal, follow its prompts, then click Install Engine again:")
                        .font(.caption)
                        .fixedSize(horizontal: false, vertical: true)
                    Text(brewCommand)
                        .font(.system(size: 10, design: .monospaced))
                        .textSelection(.enabled)
                        .padding(6)
                        .background(RoundedRectangle(cornerRadius: 6).fill(Color.secondary.opacity(0.12)))
                    HStack {
                        Button("Copy Command") {
                            NSPasteboard.general.clearContents()
                            NSPasteboard.general.setString(brewCommand, forType: .string)
                        }
                        Button("Open Terminal") {
                            NSWorkspace.shared.open(URL(fileURLWithPath: "/System/Applications/Utilities/Terminal.app"))
                        }
                    }
                }
            }
            .padding(12)
            .frame(maxWidth: .infinity, alignment: .leading)
            .background(RoundedRectangle(cornerRadius: 10).fill(Color.orange.opacity(0.12)))
        }
    }
}

struct AccountRow: View {
    @EnvironmentObject var model: AppModel

    var body: some View {
        let ok = model.hasCredentials
        HStack(spacing: 10) {
            Image(systemName: ok ? "person.crop.circle.badge.checkmark" : "person.crop.circle.badge.exclamationmark")
                .font(.system(size: 22))
                .foregroundStyle(ok ? Color.green : Color.orange)
            VStack(alignment: .leading, spacing: 2) {
                Text(ok ? "Qobuz account saved" : "No Qobuz account yet")
                    .font(.callout.weight(.medium))
                if ok {
                    Text(model.authMethod == .token ? "User ID \(model.accountID)" : model.accountID)
                        .font(.caption)
                        .foregroundStyle(.secondary)
                        .lineLimit(1)
                }
            }
            Spacer()
            Button(ok ? "Edit" : "Add…") { model.showAccount = true }
        }
        .padding(10)
        .background(RoundedRectangle(cornerRadius: 10).fill(Color.secondary.opacity(0.08)))
    }
}

// MARK: - Queue

struct QueueView: View {
    @EnvironmentObject var model: AppModel

    private var summary: String {
        let done = model.jobs.filter { $0.status == .done }.count
        return "\(model.jobs.count) item\(model.jobs.count == 1 ? "" : "s") · \(done) done"
    }

    private var hasRetryable: Bool {
        model.jobs.contains { job in
            switch job.status {
            case .failed, .cancelled, .warning: return true
            default: return false
            }
        }
    }

    var body: some View {
        VStack(spacing: 0) {
            HStack(spacing: 10) {
                Text("Queue").font(.headline)
                if !model.jobs.isEmpty {
                    Text(summary).font(.caption).foregroundStyle(.secondary)
                }
                Spacer()
                if hasRetryable && !model.isRunning {
                    Button("Retry Failed") { model.retryFailed() }
                }
                Button("Clear Finished") { model.clearFinished() }
                    .disabled(!model.jobs.contains { $0.status.isFinished })
                if model.isRunning {
                    Button(role: .destructive) {
                        model.stop()
                    } label: {
                        Label("Stop", systemImage: "stop.fill")
                    }
                } else {
                    Button {
                        model.start()
                    } label: {
                        Label("Download", systemImage: "arrow.down.circle.fill")
                    }
                    .buttonStyle(.borderedProminent)
                    .keyboardShortcut("d", modifiers: .command)
                    .disabled(!model.canStart)
                }
            }
            .padding(.horizontal, 16)
            .padding(.vertical, 10)

            Divider()

            if model.jobs.isEmpty {
                VStack(spacing: 10) {
                    Image(systemName: "music.note.list")
                        .font(.system(size: 38))
                        .foregroundStyle(.tertiary)
                    Text("Nothing queued").font(.headline)
                    Text("Paste links on the left, pick a quality, then hit Download.")
                        .font(.callout)
                        .foregroundStyle(.secondary)
                }
                .frame(maxWidth: .infinity, maxHeight: .infinity)
            } else {
                List {
                    ForEach(model.jobs) { job in
                        JobRow(job: job)
                            .contextMenu {
                                Button("Retry") { model.retry(job) }
                                    .disabled(!job.status.isFinished)
                                Button("Copy Link") {
                                    NSPasteboard.general.clearContents()
                                    NSPasteboard.general.setString(job.url, forType: .string)
                                }
                                Divider()
                                Button("Remove") { model.remove(job) }
                                    .disabled(job.status == .running)
                            }
                    }
                }
                .listStyle(.inset)
            }

            if model.isRunning && !model.statusLine.isEmpty {
                Divider()
                HStack(spacing: 8) {
                    ProgressView().controlSize(.small)
                    Text(model.statusLine)
                        .font(.callout)
                        .lineLimit(1)
                        .truncationMode(.middle)
                    Spacer()
                }
                .padding(.horizontal, 16)
                .padding(.vertical, 8)
            }
        }
    }
}

struct JobRow: View {
    let job: DownloadJob

    private var icon: (name: String, color: Color) {
        switch job.status {
        case .queued: return ("clock", .secondary)
        case .running: return ("arrow.down.circle", .accentColor)
        case .done: return ("checkmark.circle.fill", .green)
        case .warning: return ("exclamationmark.triangle.fill", .yellow)
        case .failed: return ("xmark.octagon.fill", .red)
        case .cancelled: return ("slash.circle", .secondary)
        }
    }

    private var subtitle: String {
        switch job.status {
        case .failed(let msg), .warning(let msg): return msg
        default: return job.url
        }
    }

    var body: some View {
        HStack(spacing: 12) {
            Image(systemName: icon.name)
                .font(.system(size: 16))
                .foregroundStyle(icon.color)
                .frame(width: 20)
            VStack(alignment: .leading, spacing: 2) {
                HStack(spacing: 6) {
                    Text(job.name)
                        .font(.body.weight(.medium))
                        .lineLimit(1)
                    Text(job.kind.uppercased())
                        .font(.system(size: 9, weight: .semibold))
                        .padding(.horizontal, 5)
                        .padding(.vertical, 1)
                        .background(Capsule().fill(Color.secondary.opacity(0.15)))
                }
                Text(subtitle)
                    .font(.caption)
                    .foregroundStyle(.secondary)
                    .lineLimit(1)
                    .truncationMode(.middle)
                    .help(subtitle)
            }
            Spacer()
            if job.status == .running {
                ProgressView().controlSize(.small)
            }
        }
        .padding(.vertical, 4)
    }
}

// MARK: - Log

struct LogView: View {
    @EnvironmentObject var model: AppModel

    var body: some View {
        VStack(spacing: 0) {
            HStack {
                Text("Activity").font(.headline)
                Spacer()
                Button("Copy") {
                    NSPasteboard.general.clearContents()
                    NSPasteboard.general.setString(model.log.map(\.text).joined(separator: "\n"), forType: .string)
                }
                .disabled(model.log.isEmpty)
                Button("Clear") { model.log.removeAll() }
                    .disabled(model.log.isEmpty)
            }
            .padding(.horizontal, 16)
            .padding(.vertical, 8)

            Divider()

            ScrollViewReader { proxy in
                ScrollView {
                    LazyVStack(alignment: .leading, spacing: 2) {
                        ForEach(model.log) { line in
                            Text(line.text)
                                .font(.system(size: 11, design: .monospaced))
                                .foregroundStyle(line.isError ? Color.red : Color.primary.opacity(0.85))
                                .textSelection(.enabled)
                                .frame(maxWidth: .infinity, alignment: .leading)
                                .id(line.id)
                        }
                    }
                    .padding(10)
                }
                .background(Color(nsColor: .textBackgroundColor))
                .onChange(of: model.log.count) { _ in
                    if let last = model.log.last { proxy.scrollTo(last.id, anchor: .bottom) }
                }
            }
        }
    }
}

// MARK: - Account sheet

struct AccountSheet: View {
    @EnvironmentObject var model: AppModel
    @Environment(\.dismiss) private var dismiss
    @State private var method: AuthMethod = .token
    @State private var account = ""
    @State private var secret = ""
    @State private var showHelp = false

    private var secretSaved: Bool { model.hasSecret(for: method) }
    private var canSave: Bool { !account.trimmed.isEmpty && (!secret.trimmed.isEmpty || secretSaved) }

    var body: some View {
        VStack(alignment: .leading, spacing: 16) {
            Text("Qobuz Account").font(.title2.weight(.bold))

            Picker("Sign-in method", selection: $method) {
                ForEach(AuthMethod.allCases) { m in
                    Text(m.label).tag(m)
                }
            }
            .pickerStyle(.segmented)
            .labelsHidden()

            VStack(alignment: .leading, spacing: 6) {
                Text(method == .token ? "User ID" : "Email").font(.callout.weight(.medium))
                TextField(method == .token ? "e.g. 1234567" : "you@example.com", text: $account)
                    .textFieldStyle(.roundedBorder)
            }

            VStack(alignment: .leading, spacing: 6) {
                Text(method == .token ? "Auth token" : "Password").font(.callout.weight(.medium))
                SecureField(secretSaved ? "Saved — leave empty to keep it" : "", text: $secret)
                    .textFieldStyle(.roundedBorder)
            }

            if method == .token {
                DisclosureGroup("Where do I find these?", isExpanded: $showHelp) {
                    VStack(alignment: .leading, spacing: 6) {
                        Text("1. Sign in at play.qobuz.com in Chrome or Safari.")
                        Text("2. Open Developer Tools (⌥⌘I in Chrome; in Safari, turn on the Develop menu first).")
                        Text("3. Network tab → reload the page → click any request to qobuz.com/api.json. In its request headers, the value of X-User-Auth-Token is your token.")
                        Text("4. Your numeric user ID is usually in Application → Local Storage → play.qobuz.com, in the localuser entry (field \"id\").")
                        Text("Tokens expire now and then. If downloads start failing with a login error, paste a fresh one here.")
                            .foregroundStyle(.secondary)
                    }
                    .font(.caption)
                    .fixedSize(horizontal: false, vertical: true)
                    .padding(.top, 6)
                }
            } else {
                Text("Qobuz has moved its web sign-in to a captcha-protected flow, so email + password may be rejected. If it fails, switch to User ID + Token.")
                    .font(.caption)
                    .foregroundStyle(.orange)
                    .fixedSize(horizontal: false, vertical: true)
            }

            Text("Saved in your macOS Keychain. It's written into the engine's settings only while a download runs, then removed.")
                .font(.caption)
                .foregroundStyle(.secondary)
                .fixedSize(horizontal: false, vertical: true)

            HStack {
                Spacer()
                Button("Cancel") { dismiss() }
                    .keyboardShortcut(.cancelAction)
                Button("Save") {
                    model.saveAccount(method: method, account: account, secret: secret)
                    dismiss()
                }
                .keyboardShortcut(.defaultAction)
                .disabled(!canSave)
            }
        }
        .padding(24)
        .frame(width: 500)
        .onAppear {
            method = model.authMethod
            account = model.accountID
            showHelp = !model.hasCredentials
        }
        .onChange(of: method) { newValue in
            account = newValue == model.authMethod ? model.accountID : ""
            secret = ""
        }
    }
}
